#!/usr/bin/env bash
# Сторож публичного репозитория: краснеет, если в дерево попало то, чего в нём
# быть не должно никогда (ADR 2026-10-03-0353, п. 7).
#
# Ловит:
#   1. UUID клиента — в любом файле, включая *.example: исключения по имени
#      здесь нет. Оно было и снято — им был вырезан из проверки ровно тот
#      коммитимый файл, который формой значений приглашает подставить
#      настоящее (deploy/secrets.env.example). На настоящем дереве сторож без
#      исключения даёт код 0: плейсхолдеры в примере формы улик не имеют.
#   2. готовую ссылку vless:// — именно ссылку, а не формат `vless://%s@...`
#      в bin/make-link.sh: образец требует после `vless://` начало UUID, то
#      есть улика отличает ссылку от строки-шаблона, собирающей ссылки.
#      Ветвь не дублирует п. 1: ссылку с идентификатором, не подходящим под
#      форму UUID версий 1-5, ловит только она — на это есть приманка.
#   3. приватный ИЛИ публичный ключ REALITY — 43 знака base64url после слова,
#      которым его называют на практике. Форм несколько, и это не запас:
#        `PrivateKey:` и `Password:` — так печатает сам `xray x25519`;
#        `pbk=`                      — так он стоит в готовой ссылке;
#        `ключ … :`                  — так его назовут в русском тексте
#                                      этого репозитория, а он здесь весь
#                                      русский.
#      Публичный ключ в списке не по ошибке: им проходят слой REALITY до
#      VLESS (ADR, п. 3).
#   4. shortId устройства — 8 знаков hex РЯДОМ С КОНТЕКСТОМ (`shortId`,
#      `SHORTID_…`, «short id»). Без контекста его ловить нечем: 8 знаков hex
#      встречаются в дайджестах и хешах коммитов, и общий образец краснил бы
#      на каждом пине образа.
#   5. изображение — по расширению И по первым байтам: QR-код со ссылкой
#      это та же ссылка, а `grep -I` внутрь двоичного файла не смотрит.
#
# ЧЕГО СТОРОЖ НЕ ДЕРЖИТ, названо прямо, потому что AGENTS.md ссылается на
# него как на держателя: 43 знака base64url БЕЗ слова рядом (просто строка в
# документе) и 8 знаков hex без контекста проходят. Общим образцом их не
# взять, не покраснев на каждом digest'е. Это остаётся на внимательности
# автора и на ревью, а не на CI.
#
# Почему скрипт, а не тело шага в workflow: этот же файл исполняет и шаг CI,
# и test/secrets-guard.test.sh на приманках. Проверяется поведение сторожа,
# а не его копия.
#
# В журнал Actions уходят ТОЛЬКО имена файлов: репозиторий публичный, и
# печать самой находки была бы второй публикацией секрета.
#
# Коды: 0 — чисто, 1 — находка, 2 — проверка не выполнилась.
set -euo pipefail

root="${1:-.}"
cd "$root"

UUID='[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}'
# 43 знака base64url — длина вывода `xray x25519` (32 байта без выравнивания).
B64='[A-Za-z0-9_-]{43}'
# Слово, которым ключ называют, затем до 40 любых знаков (туда попадают
# «REALITY: », «PublicKey = », кавычки и скобки), затем обязательно знак ВНЕ
# алфавита base64url и ровно 43 знака с границей справа. Границы с обеих
# сторон — то, из-за чего 64-знаковый digest сюда не попадает: любое окно из
# 43 знаков внутри него окружено знаками того же алфавита.
KEYWORD='([Kk]ey|KEY|[Pp]assword|PASSWORD|pbk|ключ|Ключ|КЛЮЧ)'
KEYLIKE="${KEYWORD}.{0,40}[^A-Za-z0-9_-]${B64}([^A-Za-z0-9_-]|\$)"
# shortId только в контексте: 8 знаков hex сами по себе — это и дайджест.
# Разрыв между словом и значением — `.{0,40}` любых знаков, а не «знаки вне
# hex»: в `SHORTID_MAC=` сразу после слова идёт `_MAC`, где `A` — знак hex, и
# класс `[^0-9a-fA-F]` на нём обрывался бы. Проверено пробой: эта форма
# пропускалась. Знаки считаются байтами, поэтому 40 — с запасом на кириллицу
# («shortId устройства: » это 23 байта).
SHORTID='([Ss]hort[ _-]?[Ii][Dd]|SHORTID|shortIds?).{0,40}[^0-9a-f][0-9a-f]{8}([^0-9a-f]|$)'
PATTERN="(^|[^0-9a-fA-F-])${UUID}([^0-9a-fA-F-]|\$)|vless://[0-9a-fA-F]{8}-|${KEYLIKE}|${SHORTID}"

found=0

# 1–3: текстовые образцы. -l: строка с находкой не печатается.
# Код grep: 0 — найдено, 1 — чисто, 2 и выше — проверка не выполнилась
# (нечитаемый файл, битая локаль). `|| rc=$?` сохраняет код и не даёт
# `set -e` оборвать скрипт на законной «не найдено».
rc=0
files=$(grep -rIlE --exclude-dir=.git -- "$PATTERN" . ) || rc=$?
if [ "$rc" -eq 0 ]; then
  echo "::error::похоже на UUID, ссылку vless://, ключ REALITY или shortId, файлы: $(printf '%s' "$files" | tr '\n' ' ' | LC_ALL=C tr '[:cntrl:]' '?')"
  found=1
elif [ "$rc" -ne 1 ]; then
  echo "::error::проверка образцов не выполнилась: grep вернул код $rc"
  exit 2
fi

# 4: изображения. Два признака, потому что одного мало: расширение ловит
# переименованный в .png текст, магические байты — QR, положенный как
# `qr-mac.bin` или `README-mac` без расширения.
while IFS= read -r file; do
  case "$file" in
    ./.git/*) continue ;;
    *.png|*.jpg|*.jpeg|*.gif|*.webp|*.svg|*.bmp|*.tiff)
      echo "::error::изображение в репозитории: $file — QR со ссылкой это та же ссылка"
      found=1
      continue
      ;;
  esac
  head -c 12 "$file" > /dev/null || { echo "::error::файл не читается: $file"; exit 2; }
  magic=$(head -c 12 "$file" | od -An -tx1 | tr -d ' \n')
  case "$magic" in
    89504e47*|ffd8ff*|47494638*)
      echo "::error::двоичное изображение под не своим именем: $file"
      found=1
      ;;
    52494646????????57454250*)
      echo "::error::двоичное изображение под не своим именем: $file"
      found=1
      ;;
  esac
done <<EOF
$(find . -type f)
EOF

if [ "$found" -ne 0 ]; then
  exit 1
fi
echo "ok: UUID, ссылок vless://, ключей REALITY, shortId и изображений не найдено"
